export function ASLogo() {
  const data = useStaticQuery(graphql`
    {
      imageSharp(fluid: { originalName: { eq: "as-logo.png" } }) {
        gatsbyImageData(
          transformOptions: {
            duotone: { highlight: "#814bff", shadow: "#814bff" }
          }
          placeholder: NONE
        )
      }
    }
  `);

  if (data) {
    return <GatsbyImage image={getImage(data.imageSharp)} />;
  } else return <></>;
}
